/*
 * A042036  Numerators of continued fraction convergents to sqrt(542).
 * https://oeis.org/A042036
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy, less
 * Formula:   a(n) = numerator of the n‑th convergent to sqrt(542). The
 *            convergents are generated by the recurrence p[−2] = 0, p[−1] =
 *            1, p[n] = a[n] · p[n−1] + p[n−2], where a[0] = ⌊√542⌋ = 23 and
 *            the subsequent a[n] are the continued‑fraction coefficients of
 *            √542: 3,1,1,3,1,1,1,22,1,1,1,3,1,1,3,46 (period 16)
 * Range:     u8 none, u16 n <= 9, u32 n <= 19, u64 n <= 43, u128 n <= 87,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* static storage for the continued‑fraction period */
    static seq_t period[64];
    static int period_len = 0;
    static seq_t a0 = 0;   /* ⌊√542⌋ */

    /* one‑time initialization */
    if (!period_len)
    {
        /* √542 floor is 23 */
        a0 = 23;

        seq_t D = 542;
        seq_t m = 0;
        seq_t d = 1;
        seq_t a = a0;

        for (;;)
        {
            m = d * a - m;
            d = (D - m * m) / d;
            a = (a0 + m) / d;
            period[period_len++] = a;
            if (a == a0 * 2)                 /* a[n] = 2*a0 indicates period end */
                break;
        }
    }

    /* recurrence for convergents */
    seq_t p_prevprev = 0;   /* p[−2] */
    seq_t p_prev     = 1;   /* p[−1] */
    seq_t p_curr;

    for (idx_t i = 0; i <= n; ++i)
    {
        seq_t a_coeff;
        if (i == 0)
            a_coeff = a0;
        else
        {
            int idx = (int)((i - 1) % (idx_t)period_len);
            a_coeff = period[idx];
        }
        p_curr = a_coeff * p_prev + p_prevprev;
        p_prevprev = p_prev;
        p_prev = p_curr;
    }

    return p_curr;
}
